#!/usr/bin/env python3
"""Build crawlable static pages for the free public Reference Catalog FROM THE DATABASE.

Output (all generated, safe to delete, rebuilt from Supabase at any time):
  reference/index.html                     overview + links to every category page
  reference/artifacts.html, fossils.html, minerals.html, texas.html
  reference/r/<slug>.html                  one lightweight page per public record
  reference/seo.css                        shared styles for these pages
  sitemap.xml                              home + the pages above
robots.txt is hand-written (not generated) and points at sitemap.xml.

Source of truth: public.reference_media rows where data->>'public' = '1' (read with the service key: SVC_KEY in the
environment, load /workspace/.svc). Only those rows are used: never user finds, never exact locations (regions are
county/state at most, as stored), never EXIF (images are the EXIF-free Storage thumbnails in bucket reference-media; a few
older rows still point at the museum's own CC0 image URL, exactly as the app shows them).
Display wording is the softened data.catalog.name; the museum's source_title is not used on these pages.

Safety: pages are built in a temporary folder, checked, and only then swapped in. If the database read fails or returns
far fewer rows than the pages already published (more than 20% drop), nothing is changed unless --force.
Usage: python3 tools/reference/build_seo_pages.py [--force] [--dry-run]"""
import argparse, datetime, html, json, os, pathlib, re, shutil, sys, tempfile, urllib.parse
ROOT = pathlib.Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / "tools/reference"))
import pc_db  # noqa: E402

SITE = "https://unearthedfinds.com/"
_m = re.search(r"ROLLING_OAK_BRAND\s*=\s*(\{.*?\});", (ROOT / "assets/js/config.js").read_text(), re.S)
BRAND = json.loads(_m.group(1)) if _m else {}
NAME = BRAND.get("name", "UnEarthed Finds"); OWNER = BRAND.get("owner", "PolForge, LLC")
OKLIC = re.compile(r"^(CC0|Public domain|CC BY(-SA)? \d\.\d)$")
# Defence in depth: anything that looks like coordinates or a precise spot is never published.
PRECISE = re.compile(r"-?\d{1,3}\.\d{3,}\s*[,; ]\s*-?\d{1,3}\.\d{3,}|\b\d{1,3}\s*°|\b(latitude|longitude|lat\.|lon\.|GPS|UTM|coordinates?)\b|\bsec(tion)?\.?\s*\d+\s*,?\s*T\d+[NS]", re.I)
CATS = {"artifact": ("artifacts", "Artifacts", "Artifact"), "fossil": ("fossils", "Fossils", "Fossil"), "mineral": ("minerals", "Minerals", "Mineral")}
_v = re.search(r'const VERSION = "([^"]+)"', (ROOT / "sw.js").read_text())
VER = _v.group(1) if _v else "1"  # cache-buster for traffic.js; tools/bump_version.sh also rewrites it in these pages
MARK = "<!-- generated by tools/reference/build_seo_pages.py from the database; do not edit by hand -->"
e = lambda s: html.escape(str(s or ""), quote=True)

def slugify(s, n=60):
    s = re.sub(r"[^a-z0-9]+", "-", str(s).lower()).strip("-")
    return s[:n].rstrip("-") or "record"
def rec_slug(x):  # stable: built from the record id; the name part only aids readability
    return f"{slugify(x['name'], 50)}-{slugify(x['id'], 40)}"

def load():
    rows = pc_db.all_rows("id,source,kind,title,thumb_url,source_url,license,license_url,attribution,data")
    out, skipped = [], []
    for r in rows:
        d = r.get("data") or {}
        if d.get("public") != "1": continue  # only public catalog records
        c = d.get("catalog") or {}
        x = {**c, "id": r["id"], "category": r["kind"], "name": c.get("name") or r["title"], "thumb": r["thumb_url"], "source": r["source"],
             "source_url": r["source_url"], "license": r["license"], "license_url": r["license_url"], "attribution": r["attribution"]}
        x.pop("source_title", None)  # softened display wording only
        text = " ".join(str(x.get(k) or "") for k in ("name", "type", "material", "period", "age", "formation", "culture", "region", "description"))
        why = ("category" if x["category"] not in CATS else "license" if not OKLIC.match(str(x["license"] or "")) else
               "image" if not str(x["thumb"] or "").startswith("https://") else
               "attribution" if not x["attribution"] else "precise-location" if PRECISE.search(text) else "")
        (skipped.append((r["id"], why)) if why else out.append(x))
    rank = {"artifact": 0, "fossil": 1, "mineral": 2}
    out.sort(key=lambda x: (rank[x["category"]], not x.get("tx"), str(x["name"]).lower(), x["id"]))
    return out, skipped

CSS = """:root{--bg:#16110D;--fg:#F3EADF;--mut:#C9B8A6;--acc:#D9A441;--card:#221A14;--line:#3A2E24}*{box-sizing:border-box}
body{margin:0;font:16px/1.5 Inter,system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:var(--bg);color:var(--fg)}
a{color:var(--acc)}header,main,footer{max-width:1100px;margin:0 auto;padding:16px 20px}header{display:flex;gap:16px;align-items:center;flex-wrap:wrap;border-bottom:1px solid var(--line)}
header .b{font-weight:700;font-size:1.15rem;text-decoration:none;color:var(--fg)}header nav{display:flex;gap:14px;flex-wrap:wrap;margin-left:auto}
h1{font-size:1.9rem;margin:.4em 0 .2em}.k{color:var(--mut);text-transform:uppercase;letter-spacing:.06em;font-size:.8rem;margin:0}.mut{color:var(--mut)}
.cta{display:flex;gap:12px;flex-wrap:wrap;margin:16px 0}.btn{display:inline-block;padding:10px 16px;border-radius:999px;background:var(--acc);color:#16110D;font-weight:600;text-decoration:none}.btn.o{background:none;color:var(--acc);border:1px solid var(--acc)}
ul.g{list-style:none;padding:0;display:grid;grid-template-columns:repeat(auto-fill,minmax(170px,1fr));gap:14px}ul.g li{background:var(--card);border:1px solid var(--line);border-radius:12px;overflow:hidden}
ul.g a{display:block;text-decoration:none;color:var(--fg)}ul.g img{width:100%;aspect-ratio:1;object-fit:cover;display:block;background:#000}ul.g span{display:block;padding:8px 10px;font-size:.9rem}ul.g small{display:block;padding:0 10px 10px;color:var(--mut)}
.rec{display:grid;grid-template-columns:minmax(240px,480px) 1fr;gap:24px;align-items:start}.rec img{width:100%;height:auto;border-radius:12px;background:#000}@media(max-width:720px){.rec{grid-template-columns:1fr}}
dl{display:grid;grid-template-columns:max-content 1fr;gap:4px 14px}dt{color:var(--mut)}dd{margin:0}.cats{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:14px;padding:0;list-style:none}
.cats a{display:block;padding:16px;border:1px solid var(--line);border-radius:12px;background:var(--card);text-decoration:none;color:var(--fg)}.cats strong{display:block;font-size:1.2rem;color:var(--acc)}
footer{border-top:1px solid var(--line);color:var(--mut);font-size:.85rem;margin-top:24px}"""

def page(path, title, desc, body, image=None, img_alt="", ld=None, og_type="website", rec=None):
    url = SITE + path
    image = image or SITE + "assets/brand/og-image.png"
    lds = "".join(f'<script type="application/ld+json">{json.dumps(o, ensure_ascii=False).replace("</", "<\\/")}</script>' for o in (ld or []))
    up = "../" * path.count("/")
    return f"""<!DOCTYPE html>
{MARK}
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>{e(title)}</title><meta name="description" content="{e(desc)}"><link rel="canonical" href="{e(url)}"><meta name="robots" content="index, follow, max-image-preview:large">
<meta property="og:type" content="{og_type}"><meta property="og:site_name" content="{e(NAME)}"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(desc)}">
<meta property="og:url" content="{e(url)}"><meta property="og:image" content="{e(image)}"><meta property="og:image:alt" content="{e(img_alt or title)}">
<meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{e(title)}"><meta name="twitter:description" content="{e(desc)}"><meta name="twitter:image" content="{e(image)}">
<link rel="icon" href="{up}favicon.ico" sizes="any"><link rel="apple-touch-icon" href="{up}assets/brand/apple-touch-icon.png"><meta name="theme-color" content="#16110D">
<link rel="stylesheet" href="{up}reference/seo.css">{lds}{f'<meta name="uf-rec" content="{e(rec)}">' if rec else ""}<script src="{up}assets/js/traffic.js?v={e(VER)}" defer></script></head>
<body><header><a class="b" href="{up}">{e(NAME)}</a><nav aria-label="Reference Catalog"><a href="{up}reference/">Reference Catalog</a><a href="{up}reference/artifacts.html">Artifacts</a><a href="{up}reference/fossils.html">Fossils</a><a href="{up}reference/minerals.html">Minerals</a><a href="{up}reference/texas.html">Texas</a><a href="{up}#/try">Try it free</a></nav></header>
<main>{body}</main>
<footer><p>Museum images are shown under their stated open licenses with the institution's credit line. Locations are given at county or state level only. These are look-alike references for research, not identifications of anyone's find.</p>
<p>© {datetime.date.today().year} {e(OWNER)} · <a href="{up}#/about">About &amp; legal</a> · <a href="{up}#/privacy">Privacy</a></p></footer></body></html>
"""

def facts(x): return [v for v in (x.get("type"), x.get("material") if x.get("material") != x["name"] else "", x.get("period") or x.get("age"), x.get("region")) if v]
def card(x, up=""):
    return (f'<li><a href="{up}r/{rec_slug(x)}.html"><img src="{e(x["thumb"])}" alt="{e(x["name"])}" loading="lazy" decoding="async" width="240" height="240">'
            f'<span>{e(x["name"])}</span></a><small>{e(" · ".join(facts(x)[:2]))}<br>{e(x.get("institution"))} · {e(x["license"])}</small></li>')
def app_link(x): return SITE + "#/reference/" + urllib.parse.quote(x["id"], safe="")
def cta(x=None):
    a = f'<a class="btn" href="{e(app_link(x))}">Open in the app</a>' if x else f'<a class="btn" href="{SITE}#/reference">Search the full catalog in the app</a>'
    return f'<div class="cta">{a}<a class="btn o" href="{SITE}#/try">Try it free: catalog your own find</a></div>'

def build(items, out):
    (out / "r").mkdir(parents=True); (out / "seo.css").write_text(CSS + "\n")
    n = {k: sum(1 for x in items if x["category"] == k) for k in CATS}; tx = [x for x in items if x.get("tx")]
    insts = sorted({x.get("institution") for x in items if x.get("institution")})
    org = {"@type": "Organization", "name": OWNER}
    # ---- record pages ----
    for x in items:
        cat = CATS[x["category"]][2]; slug = rec_slug(x); path = f"reference/r/{slug}.html"
        bits = facts(x)
        title = f'{x["name"]} ({cat.lower()}) | Free Reference Catalog | {NAME}'
        desc = f'{cat}: {x["name"]}' + (f' ({", ".join(bits[:3])})' if bits else "") + f'. Held by {x.get("institution") or x["source"]}. {x["license"]} museum image, free to browse.'
        desc = desc[:300]
        row = lambda k, v: f"<dt>{e(k)}</dt><dd>{e(v)}</dd>" if v else ""
        lic = f'<a href="{e(x["license_url"])}" rel="license noopener nofollow">{e(x["license"])}</a>' if x.get("license_url") else e(x["license"])
        body = (f'<p class="k">{cat} · Free reference record</p><h1>{e(x["name"])}</h1>{cta(x)}<div class="rec"><img src="{e(x["thumb"])}" alt="{e(x["name"])}" width="480" height="480">'
                f'<div><dl>{row("Type", x.get("type"))}{row("Material", x.get("material"))}{row("Period", x.get("period"))}{row("Age / date", x.get("age"))}{row("Formation", x.get("formation"))}'
                f'{row("Culture area", x.get("culture"))}{row("Region", x.get("region") or "Not stated")}{row("Held by", x.get("institution"))}{row("Catalog no.", x.get("catalog_number"))}{row("Notes", x.get("description"))}</dl>'
                f'<p><strong>Credit:</strong> {e(x["attribution"])}</p><p><strong>License:</strong> {lic} · <a href="{e(x["source_url"])}" rel="noopener nofollow">View the original record ({e(x["source"])})</a></p>'
                f'<p class="mut">Image resized to a thumbnail. Location shown at county or state level only. Reference for research, not an identification of anyone\'s find.</p>'
                f'<p>More: <a href="../{CATS[x["category"]][0]}.html">all {CATS[x["category"]][1].lower()}</a>' + (' · <a href="../texas.html">Texas records</a>' if x.get("tx") else "") + ' · <a href="../">Reference Catalog home</a></p></div></div>')
        img = {"@type": "ImageObject", "contentUrl": x["thumb"], "license": x.get("license_url") or x["license"], "acquireLicensePage": x["source_url"],
               "creditText": x["attribution"], "creator": {"@type": "Organization" if not x.get("creator") or x.get("creator") == x.get("institution") or re.search(r"Museum|Smithsonian|NMNH|Institut|Universit|Department|Survey|Society|Library|Collection|Open Access", x["creator"]) else "Person", "name": x.get("creator") or x.get("institution") or x["source"]},
               "copyrightNotice": x["attribution"]}
        work = {"@context": "https://schema.org", "@type": "CreativeWork", "name": x["name"], "description": desc, "url": SITE + path, "image": img,
                "license": x.get("license_url") or x["license"], "creditText": x["attribution"], "isAccessibleForFree": True,
                "provider": {"@type": "Organization", "name": x.get("institution") or x["source"]}, "sameAs": x["source_url"],
                "isPartOf": {"@type": "CollectionPage", "name": f"{NAME} Reference Catalog", "url": SITE + "reference/"},
                "keywords": ", ".join(v for v in (cat, x.get("type"), x.get("period"), x.get("region")) if v)}
        if x.get("catalog_number"): work["identifier"] = x["catalog_number"]
        (out / "r" / f"{slug}.html").write_text(page(path, title, desc, body, x["thumb"], x["name"], [work], "article", rec=x["id"]))
    # ---- category + Texas pages ----
    def listing(fname, h1, kicker, intro, subset, short):
        path = f"reference/{fname}"
        title = f"{h1} | Free Reference Catalog | {NAME}"
        desc = f"{intro} {len(subset):,} records with open-licensed museum photos, free to browse, no sign-up."[:300]
        body = f'<p class="k">{e(kicker)}</p><h1>{e(h1)}</h1><p>{e(intro)} {len(subset):,} records.</p>{cta()}<ul class="g">' + "".join(card(x) for x in subset) + "</ul>"
        ld = {"@context": "https://schema.org", "@type": "CollectionPage", "name": h1, "description": desc, "url": SITE + path, "isAccessibleForFree": True, "publisher": org,
              "mainEntity": {"@type": "ItemList", "numberOfItems": len(subset), "itemListElement": [{"@type": "ListItem", "position": i + 1, "url": SITE + f"reference/r/{rec_slug(x)}.html", "name": x["name"]} for i, x in enumerate(subset[:200])]}}
        (out / fname).write_text(page(path, title, desc, body, subset[0]["thumb"] if subset else None, short, [ld]))
    listing("artifacts.html", "Artifacts: museum reference collection", "Free Reference Catalog · Artifacts", "Projectile points, stone tools and other artifacts held by museums, with open-licensed photos.", [x for x in items if x["category"] == "artifact"], "Artifacts")
    listing("fossils.html", "Fossils: museum reference collection", "Free Reference Catalog · Fossils", "Fossil specimens held by museums and research collections, with open-licensed photos.", [x for x in items if x["category"] == "fossil"], "Fossils")
    listing("minerals.html", "Minerals: museum reference collection", "Free Reference Catalog · Minerals", "Mineral and rock specimens held by museums, with open-licensed photos.", [x for x in items if x["category"] == "mineral"], "Minerals")
    listing("texas.html", "Texas artifacts, fossils and minerals", "Free Reference Catalog · Texas", "Museum-held artifacts, fossils and minerals from Texas, located to county level at most.", tx, "Texas records")
    # ---- index ----
    feat = []
    for k in CATS: feat += [x for x in items if x["category"] == k and x.get("tx")][:8] or [x for x in items if x["category"] == k][:8]
    title = f"Free Reference Catalog of artifacts, fossils and minerals | {NAME}"
    desc = f"Browse {len(items):,} museum-held artifacts, fossils and minerals with free, open-licensed photos ({len(tx):,} from Texas). No sign-up. Credits and licenses on every record."
    body = (f'<p class="k">Free &amp; public · No sign-up</p><h1>Free Reference Catalog</h1><p>{len(items):,} artifacts, fossils and minerals held by museums, each with an open-licensed photo, '
            f'its institution, catalog number and credit line. Use it to compare your own finds. Sources: {e(", ".join(insts))}.</p>{cta()}'
            f'<ul class="cats"><li><a href="artifacts.html"><strong>{n["artifact"]:,}</strong>Artifacts</a></li><li><a href="fossils.html"><strong>{n["fossil"]:,}</strong>Fossils</a></li>'
            f'<li><a href="minerals.html"><strong>{n["mineral"]:,}</strong>Minerals</a></li><li><a href="texas.html"><strong>{len(tx):,}</strong>From Texas</a></li></ul>'
            f'<h2>A few records</h2><ul class="g">' + "".join(card(x) for x in feat) + "</ul>"
            f'<p class="mut">New records are added every week from museum open-access collections.</p>')
    ld = [{"@context": "https://schema.org", "@type": "CollectionPage", "name": f"{NAME} Free Reference Catalog", "description": desc, "url": SITE + "reference/", "isAccessibleForFree": True, "publisher": org,
           "hasPart": [{"@type": "CollectionPage", "name": t, "url": SITE + f"reference/{f}"} for f, t in (("artifacts.html", "Artifacts"), ("fossils.html", "Fossils"), ("minerals.html", "Minerals"), ("texas.html", "Texas"))]}]
    (out / "index.html").write_text(page("reference/", title, desc, body, feat[0]["thumb"] if feat else None, "Reference Catalog", ld))
    return n, len(tx)

def sitemap(items, day):
    urls = [(SITE, "weekly", "1.0"), (SITE + "reference/", "weekly", "0.9")] + [(SITE + f"reference/{f}", "weekly", "0.8") for f in ("artifacts.html", "fossils.html", "minerals.html", "texas.html")]
    urls += [(SITE + f"reference/r/{rec_slug(x)}.html", "monthly", "0.5") for x in items]
    return '<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n' + "".join(
        f"  <url><loc>{html.escape(u)}</loc>{'' if '/r/' in u else f'<lastmod>{day}</lastmod>'}<changefreq>{c}</changefreq><priority>{p}</priority></url>\n" for u, c, p in urls) + "</urlset>\n"

def main():
    ap = argparse.ArgumentParser(); ap.add_argument("--force", action="store_true"); ap.add_argument("--dry-run", action="store_true"); a = ap.parse_args()
    items, skipped = load()
    slugs = [rec_slug(x) for x in items]
    if len(set(slugs)) != len(slugs): raise SystemExit("slug collision; nothing changed")
    if not items: raise SystemExit("database returned no public records; nothing changed")
    dest = ROOT / "reference"; old = len(list((dest / "r").glob("*.html"))) if (dest / "r").exists() else 0
    if old and len(items) < old * 0.8 and not a.force: raise SystemExit(f"database returned {len(items)} records but {old} pages are published (>20% drop); nothing changed. Re-run with --force if intended.")
    tmp = pathlib.Path(tempfile.mkdtemp(prefix="seo-", dir=ROOT)) / "reference"
    try:
        n, ntx = build(items, tmp)
        bad = [p.name for p in tmp.rglob("*.html") if "<title>" not in (t := p.read_text()) or 'rel="canonical"' not in t or "application/ld+json" not in t]
        if bad: raise SystemExit(f"generated pages failed checks: {bad[:5]}; nothing changed")
        day = datetime.date.today().isoformat(); sm = sitemap(items, day)
        if a.dry_run: print(f"dry run: {len(items)} records ({n}), {ntx} Texas, skipped {len(skipped)}"); return
        if dest.exists():  # generated folder only: replace it as a whole
            if not (dest / "index.html").exists() or MARK not in (dest / "index.html").read_text(): raise SystemExit("reference/ exists but was not generated by this script; nothing changed")
            shutil.rmtree(dest)
        shutil.move(str(tmp), str(dest))
        (ROOT / "sitemap.xml").write_text(sm)
    finally:
        shutil.rmtree(tmp.parent, ignore_errors=True)
    print(f"seo pages: {len(items)} record pages (artifact {n['artifact']}, fossil {n['fossil']}, mineral {n['mineral']}), Texas {ntx}, 5 index pages, sitemap {len(items) + 6} URLs; skipped {len(skipped)}"
          + (f" {sorted(set(w for _, w in skipped))}" if skipped else ""))

if __name__ == "__main__": main()
